void print_report() const {
    constexpr int operation_width = 29;
    constexpr int time_width = 11;
    constexpr int percent_width = 8;
    constexpr int calls_width = 8;
    constexpr int ms_per_call_width = 10;

    auto total_ms = std::chrono::duration<double, std::milli>(
        get_points_from_grid + get_conv_from_grid + find_F +
        polygon_construct + boost_intersection +
        validation + loop_overhead + dead_check + result_handling + state_update
    ).count();

    std::cout << "\n========== TIMING REPORT ==========\n";
    std::cout << "Operation                    |  Time (ms) |       % |   Calls |   ms/call\n";
    std::cout << "-----------------------------|------------|---------|---------|------------\n";

    auto print_row = [&](const char* name, Duration dur, long long calls) {
        auto ms = std::chrono::duration<double, std::milli>(dur).count();
        double pct = total_ms > 0 ? (ms / total_ms) * 100 : 0;
        double ms_per_call = calls > 0 ? ms / calls : 0;

        std::cout << std::left << std::setw(operation_width) << name << "| "
                  << std::right << std::fixed << std::setprecision(2)
                  << std::setw(time_width) << ms << " | "
                  << std::setw(percent_width - 1) << std::setprecision(1) << pct << "% | "
                  << std::setw(calls_width) << std::setprecision(0) << calls << " | "
                  << std::setw(ms_per_call_width) << std::setprecision(4) << ms_per_call << "\n";
    };

    print_row("get_points_from_grid", get_points_from_grid, get_points_from_grid_calls);
    print_row("get_conv_from_grid", get_conv_from_grid, get_conv_from_grid_calls);
    print_row("find_F", find_F, find_F_calls);
    print_row("polygon_construct", polygon_construct, polygon_construct_calls);
    print_row("boost_intersection", boost_intersection, boost_intersection_calls);
    print_row("validation", validation, boost_intersection_calls);
    print_row("dead_check", dead_check, boost_intersection_calls);
    print_row("result_handling", result_handling, boost_intersection_calls);
    print_row("state_update", state_update, boost_intersection_calls);
    print_row("loop_overhead", loop_overhead, 1);
    std::cout << "-----------------------------|------------|---------|---------|------------\n";
    std::cout << "Intersection result agreement: "
              << intersection_result_matches << " match, "
              << intersection_result_mismatches << " mismatch\n";
}

